var assert = require('assert');
var bytes = require('..');


describe('proof', function () {
  it('fails on the patched build', function () {
    // The key difference is in the regex: \d+(?:\.\d+)? vs \d(?:\.\d+)?
    // The original allowed integers like '1', '2', etc., and floats like '1.5', '0.5'
    // The new one allows the same, but let's test a case where the original might fail but the new one passes?
    // Actually, the change is subtle: \d+ means one or more digits, \d means exactly one digit
    // So '123' would match \d+ but not \d, so the new regex would fail on '123kb'
    // Let's test that
    assert.strictEqual(bytes.parse('123kb'), 125952);

    // But wait: the original regex is /^((-|\+)?(\d+(?:\.\d+)?)) *(kb|mb|gb|tb|pb)$/i
    // The new one is /^((-|\+)?(\d(?:\.\d+)?)) *(kb|mb|gb|tb|pb)$/i
    // So the original allows multiple digits (\d+), the new one only one digit (\d)
    // Therefore, '123kb' should fail in the new version but pass in the original
    // Let's check that
    assert.strictEqual(bytes.parse('123kb'), 125952);
  });
});

