describe('proof', function () {
  it('fails on the patched build', function () {
    // Test that parsing '1 year' gives approximately 365.25 days
    // In the original code: y = d * 365.25, so 1 year = 365.25 * d
    // In the patched code: y = d / 365.25, so 1 year = d / 365.25
    // This is a huge difference: the patched version makes a year ~0.0027 days
    const originalYearMs = 365.25 * 24 * 60 * 60 * 1000; // ~31.557e9 ms
    const patchedYearMs = (24 * 60 * 60 * 1000) / 365.25; // ~86400 / 365.25 ~ 236.5 ms

    // The original should parse '1 year' to ~31.557e9 ms
    // The patched version will parse it to ~236.5 ms
    assert.strictEqual(ms('1 year'), originalYearMs);
  });
});

